import json,re,os,glob
cat=json.load(open('harnesses/codex/catalog.json'))
rt={}
for p in cat['plugins']:
    files=set()
    for f in p['runtime_files']:
        files.add(f if isinstance(f,str) else f['source'])
    rt[p['id']]=files
glob_rt=[f['source'] if isinstance(f,dict) else f for f in cat['runtime_files']]
print('global',glob_rt)
pat=re.compile(r'(shared/[A-Za-z0-9_@./\-\*]+)')
def covered(path,files):
    path=path.rstrip('.,;:)`')
    for f in files:
        if path==f or path.startswith(f.rstrip('/')+'/'): return True
    return False
for pid in rt:
    base=f'harnesses/codex/plugins/{pid}'
    for f in glob.glob(base+'/**/*',recursive=True):
        if not os.path.isfile(f): continue
        t=open(f,errors='ignore').read()
        for m in set(pat.findall(t)):
            m=m.rstrip('.,;:)`')
            if '*' in m or '<' in m: continue
            ex=os.path.exists(m)
            if not ex: print('MISSING',pid,f,m)
            elif not covered(m,rt[pid]): print('NOTSHIPPED',pid,f,m)
for f in glob.glob('harnesses/codex/agent-roles/*'):
    t=open(f).read()
    for m in set(pat.findall(t)):
        m=m.rstrip('.,;:)`')
        print('ROLE',f,m, os.path.exists(m))
