import re,os,glob
pat=re.compile(r'\$\{CLAUDE_PLUGIN_ROOT\}/([A-Za-z0-9_@./\-]+)')
rel=re.compile(r'\]\((\.{1,2}/[^)#]+)')
bad=0
for pdir in sorted(glob.glob('plugins/*')):
    for root,ds,fs in os.walk(pdir):
        # do not follow symlinked shared (scan once under /shared)
        ds[:]=[d for d in ds if not os.path.islink(os.path.join(root,d))]
        for f in fs:
            if not f.endswith(('.md','.json','.sh','.py')): continue
            p=os.path.join(root,f)
            t=open(p,errors='ignore').read()
            for m in set(pat.findall(t)):
                m=m.rstrip('.,;:)`')
                if '<' in m or '*' in m: continue
                if not os.path.exists(os.path.join(pdir,m)):
                    print('MISSING',p,m); bad+=1
# shared: relative refs and shared/ refs
for root,ds,fs in os.walk('shared'):
    for f in fs:
        if not f.endswith('.md'): continue
        p=os.path.join(root,f)
        t=open(p,errors='ignore').read()
        for m in set(rel.findall(t)):
            tgt=os.path.normpath(os.path.join(root,m))
            if not os.path.exists(tgt): print('SHARED-REL-MISSING',p,m)
        for m in set(re.findall(r'(?<![A-Za-z/])((?:references|schemas)/[A-Za-z0-9_@./\-]+\.(?:md|json))',t)):
            cand=[os.path.join('shared',m), os.path.join(root,m)]
            if not any(os.path.exists(c) for c in cand): print('SHARED-BARE-MISSING',p,m)
        for m in set(re.findall(r'shared/(?:references|schemas|hooks|scripts)/[A-Za-z0-9_@./\-]+\.(?:md|json|py|sh)',t)):
            if not os.path.exists(m): print('SHARED-PATH-MISSING',p,m)
# docs, README, root md: referenced files
for p in ['AGENTS.md','README.md','ARCHITECTURE.md','CONTRIBUTING.md']+[os.path.join(r,f) for r,d,fs in os.walk('docs') for f in fs if f.endswith('.md')]:
    t=open(p,errors='ignore').read()
    for m in set(re.findall(r'\]\((\.{0,2}/?[A-Za-z0-9_@./\-]+\.(?:md|json|py|sh|yml))(?:#[^)]*)?\)',t)):
        if m.startswith('http'): continue
        tgt=os.path.normpath(os.path.join(os.path.dirname(p),m))
        if not os.path.exists(tgt): print('DOC-LINK-MISSING',p,m)
print('done',bad)

