import json,re,os
cat=json.load(open('harnesses/codex/catalog.json'))
pat=re.compile(r'(?<![A-Za-z0-9_/.-])((?:shared/)?(?:references|schemas)/[A-Za-z0-9_@./\-]+\.(?:md|json))')
def expand(entries):
    out=set()
    for e in entries:
        p=e if isinstance(e,str) else e['source']
        if os.path.isdir(p):
            for r,d,fs in os.walk(p):
                for f in fs: out.add(os.path.join(r,f))
        else: out.add(p)
    return out
for pl in cat['plugins']:
    shipped=expand(pl['runtime_files'])
    for f in sorted(shipped):
        if not f.endswith('.md'): continue
        t=open(f).read()
        if 'CLAUDE_PLUGIN_ROOT' in t: print('CLAUDEROOT-IN-SHIPPED',pl['id'],f)
        for m in set(pat.findall(t)):
            full=m if m.startswith('shared/') else 'shared/'+m
            if full.rstrip('.,') not in shipped and os.path.exists(full):
                print('TRANSITIVE-NOT-SHIPPED',pl['id'],f,'->',full)
            elif not os.path.exists(full):
                print('TRANSITIVE-MISSING',pl['id'],f,'->',full)
    # also schema $ref to other schemas
    for f in sorted(shipped):
        if f.endswith('.json') and 'schemas' in f:
            t=open(f).read()
            for m in set(re.findall(r'"\$ref"\s*:\s*"([^"#]+)',t)):
                tgt=os.path.normpath(os.path.join(os.path.dirname(f),m))
                if tgt not in shipped: print('SCHEMA-REF-NOT-SHIPPED',pl['id'],f,m)

